import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream is = System.in;

    static int readByte() throws IOException {
        if (ptr == len) { len = is.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static String next() throws IOException {
        int c = readByte();
        while (c != -1 && c <= ' ') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = readByte(); }
        return sb.toString();
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c != '-' && (c < '0' || c > '9')) c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = readByte(); }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int R = (int) nextLong();
        long[][] g = new long[R][];
        int total = 0;
        for (int r = 0; r < R; r++) {
            int c = (int) nextLong();
            g[r] = new long[c];
            for (int j = 0; j < c; j++) g[r][j] = nextLong();
            total += c;
        }
        Integer[] cells = new Integer[total]; // encoded as r * 16 + c
        int t = 0;
        for (int r = 0; r < R; r++) for (int c = 0; c < g[r].length; c++) cells[t++] = r * 16 + c;
        // descending values: every larger neighbour is finished before the cell
        Arrays.sort(cells, (x, y) -> Long.compare(g[y / 16][y % 16], g[x / 16][x % 16]));
        long[][] ways = new long[R][];
        for (int r = 0; r < R; r++) ways[r] = new long[g[r].length];
        long answer = 0;
        int[] dr = {-1, 1, 0, 0}, dc = {0, 0, -1, 1};
        for (int cell : cells) {
            int r = cell / 16, c = cell % 16;
            long count = 0; // paths starting here with at least one more step
            for (int k = 0; k < 4; k++) {
                int nr = r + dr[k], nc = c + dc[k];
                if (nr >= 0 && nr < R && nc >= 0 && nc < g[nr].length && g[nr][nc] > g[r][c]) count += 1 + ways[nr][nc];
            }
            ways[r][c] = count;
            answer += count;
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

func main() {
	rd := bufio.NewReader(os.Stdin)
	var R int
	fmt.Fscan(rd, &R)
	g := make([][]int64, R)
	var cells [][2]int
	for r := range g {
		var c int
		fmt.Fscan(rd, &c)
		g[r] = make([]int64, c)
		for j := range g[r] {
			fmt.Fscan(rd, &g[r][j])
			cells = append(cells, [2]int{r, j})
		}
	}
	exists := func(r, c int) bool { return r >= 0 && r < R && c >= 0 && c < len(g[r]) }
	// descending values: every larger neighbour is finished before the cell
	sort.SliceStable(cells, func(a, b int) bool { return g[cells[a][0]][cells[a][1]] > g[cells[b][0]][cells[b][1]] })
	ways := make([][]int64, R)
	for r := range ways {
		ways[r] = make([]int64, len(g[r]))
	}
	var answer int64
	dr := [4]int{-1, 1, 0, 0}
	dc := [4]int{0, 0, -1, 1}
	for _, cell := range cells {
		r, c := cell[0], cell[1]
		var count int64 // paths starting here with at least one more step
		for k := 0; k < 4; k++ {
			nr, nc := r+dr[k], c+dc[k]
			if exists(nr, nc) && g[nr][nc] > g[r][c] {
				count += 1 + ways[nr][nc]
			}
		}
		ways[r][c] = count
		answer += count
	}
	fmt.Println(answer)
}
